public static function normalize(string $value, int $scale = self::MONEY_SCALE): string
{
    $negative = str_starts_with($value, '-');
    $abs = $negative ? substr($value, 1) : $value;
    [$int, $frac] = str_contains($abs, '.') ? explode('.', $abs, 2) : [$abs, ''];
    if ($int === '') $int = '0';
    $int = ltrim($int, '0') ?: '0';
    $frac = str_pad(substr($frac, 0, $scale), $scale, '0');
    $result = $int . '.' . $frac;
    if ($negative && !( $int === '0' )) return '-'.$result;
    return $result;
}
```
